<script setup>
import { computed, reactive, ref } from 'vue'

const densityTabs=[['results','结果'],['compare','layer 对比'],['gradient','梯度 Spec'],['history','历史'],['fa','FA 关联']]
const patternTabs=[['pattern','Pattern Match 结果'],['fa','FA 关联']]
const activeTab=ref('setup')
const selectedTaskId=ref(null)
const selectedTaskIds=ref([])
const tasks=ref([])
const tclInput=ref('density::analyze -layer M1 -step 100')
const tclLog=ref([])
const common=reactive({project:'',gdsName:''})
const densityForm=reactive({layer:'M1',compareLayer:'M2',stepUm:100,widthUm:500,heightUm:500,negativeSpec:-0.08,positiveSpec:0.08})
const patternForm=reactive({patternFile:'pattern.xml'})

const selectedTask=computed(()=>tasks.value.find(t=>t.id===selectedTaskId.value)||null)
const resultTabs=computed(()=>selectedTask.value?.type==='pattern'?patternTabs:densityTabs)
const allSelected=computed(()=>tasks.value.length>0&&tasks.value.every(t=>selectedTaskIds.value.includes(t.id)))

function seed(text){let v=0;for(const c of String(text))v=(v*31+c.charCodeAt(0))>>>0;return v}
function densityValues(key,count=120,shift=0){return Array.from({length:count},(_,i)=>Number((.38+((seed(`${key}-${i}`)%210)/1000)+shift).toFixed(4)))}
function makeDensityResult(task){const values=densityValues(task.id);const mean=values.reduce((a,b)=>a+b,0)/values.length;const variance=values.reduce((a,b)=>a+(b-mean)**2,0)/values.length;const signedGradients=values.slice(1).map((v,i)=>Number((v-values[i]).toFixed(4)));const maxAbsGradient=Math.max(...signedGradients.map(Math.abs));const pValue=.06+(task.id%25)/100;return{values,mean,variance,signedGradients,maxAbsGradient,pValue,pass:signedGradients.every(v=>v>=task.negativeSpec&&v<=task.positiveSpec)&&pValue>=.05}}
function makePatternResult(task){const matched=(seed(`${task.id}-${task.patternFile}`)%5)!==0;const count=matched?1+(seed(task.patternFile)%24):0;return{matched,count,score:matched?Number((.86+(seed(task.id)%120)/1000).toFixed(3)):Number((.42+(seed(task.id)%180)/1000).toFixed(3))}}
function nextName(prefix){const n=tasks.value.filter(t=>t.type===prefix).length+1;return`${prefix==='density'?'DENSITY':'PATTERN'}-${String(n).padStart(3,'0')}`}
function createDensityTask(source='form'){const id=Date.now()+tasks.value.length;const task={id,type:'density',name:nextName('density'),project:common.project||'未命名项目',gdsName:common.gdsName||'demo.gds',layer:densityForm.layer,compareLayer:densityForm.compareLayer,stepUm:Number(densityForm.stepUm),widthUm:Number(densityForm.widthUm),heightUm:Number(densityForm.heightUm),negativeSpec:Number(densityForm.negativeSpec),positiveSpec:Number(densityForm.positiveSpec),source,createdAt:new Date().toLocaleString()};task.result=makeDensityResult(task);tasks.value.unshift(task);selectedTaskId.value=task.id;activeTab.value='setup'}
function createPatternTask(){const id=Date.now()+tasks.value.length;const task={id,type:'pattern',name:nextName('pattern'),project:common.project||'未命名项目',gdsName:common.gdsName||'demo.gds',patternFile:patternForm.patternFile||'pattern.xml',source:'表单',createdAt:new Date().toLocaleString()};task.result=makePatternResult(task);tasks.value.unshift(task);selectedTaskId.value=task.id;activeTab.value='setup'}
function openTask(task){selectedTaskId.value=task.id;activeTab.value=task.type==='pattern'?'pattern':'results'}
function backToSetup(){activeTab.value='setup'}
function toggleTask(id){selectedTaskIds.value=selectedTaskIds.value.includes(id)?selectedTaskIds.value.filter(x=>x!==id):[...selectedTaskIds.value,id]}
function toggleAll(){selectedTaskIds.value=allSelected.value?[]:tasks.value.map(t=>t.id)}
function runTcl(){const command=tclInput.value.trim();if(!command)return;const layer=command.match(/-layer\s+(\S+)/i),step=command.match(/-step\s+(\d+(?:\.\d+)?)/i);if(layer)densityForm.layer=layer[1];if(step)densityForm.stepUm=Number(step[1]);const creates=/density::analyze|density::create/i.test(command);tclLog.value.unshift({command,time:new Date().toLocaleTimeString(),output:creates?'已新增一条 density 分析任务。':'command 已执行。'});if(creates)createDensityTask('tcl')}
function updateSpecs(){if(!selectedTask.value||selectedTask.value.type!=='density')return;selectedTask.value.negativeSpec=Number(selectedTask.value.negativeSpec);selectedTask.value.positiveSpec=Number(selectedTask.value.positiveSpec);selectedTask.value.result.pass=selectedTask.value.result.signedGradients.every(v=>v>=selectedTask.value.negativeSpec&&v<=selectedTask.value.positiveSpec)&&selectedTask.value.result.pValue>=.05}
const compareValues=computed(()=>selectedTask.value?.type==='density'?densityValues(`${selectedTask.value.id}-${selectedTask.value.compareLayer}`,120,-.012):[])
const gradientRange=computed(()=>{if(selectedTask.value?.type!=='density')return .1;return Math.max(Math.abs(selectedTask.value.negativeSpec),Math.abs(selectedTask.value.positiveSpec),...selectedTask.value.result.signedGradients.map(Math.abs),.01)})
const gradientBins=computed(()=>{if(selectedTask.value?.type!=='density')return[];const vals=selectedTask.value.result.signedGradients;const max=gradientRange.value;const count=16;return Array.from({length:count},(_,i)=>{const lo=-max+(2*max*i/count),hi=-max+(2*max*(i+1)/count);return{lo,hi,count:vals.filter(v=>v>=lo&&(i===count-1?v<=hi:v<hi)).length}})})
const historyData=computed(()=>selectedTask.value?.type==='density'?[{project:selectedTask.value.project||'当前项目',density:selectedTask.value.result.mean,gradient:selectedTask.value.result.maxAbsGradient},{project:'History-A',density:.468,gradient:.061},{project:'History-B',density:.451,gradient:.073},{project:'History-C',density:.492,gradient:.052},{project:'History-D',density:.438,gradient:.081}]:[])
const faCases=computed(()=>{if(!selectedTask.value)return[];const p=selectedTask.value.project||'Demo';return[{caseId:'FA-2026-00127',project:p,product:'Falcon-A',technology:'N5',failType:'Open',failModel:'Via open / high resistance',layer:selectedTask.value.layer||'M1',sem:'open'},{caseId:'FA-2026-00142',project:p,product:'Falcon-A',technology:'N5',failType:'Short',failModel:'Metal bridge',layer:selectedTask.value.compareLayer||'M2',sem:'bridge'},{caseId:'FA-2026-00168',project:p,product:'Falcon-B',technology:'N5',failType:'Leakage',failModel:'Local density hotspot correlation',layer:selectedTask.value.layer||'M1',sem:'hotspot'},{caseId:'FA-2026-00191',project:p,product:'Falcon-B',technology:'N4',failType:'Timing',failModel:'CMP dishing / RC shift',layer:selectedTask.value.layer||'M1',sem:'dishing'}]})
function heatColor(v){const t=Math.max(0,Math.min(1,(v-.38)/.21));const hue=220-t*190;return`hsl(${hue} 76% 52%)`}
function specPosition(v){const max=gradientRange.value;return Math.max(0,Math.min(100,((v+max)/(2*max))*100))}
</script>

<template>
<main class="density-task-page">
<header class="page-head"><div><div class="eyebrow">GDS · density · pattern match</div><h1>GDS 分析</h1><p>项目和 GDS 为公共输入，可分别创建 density 或 pattern match 任务。</p></div><button v-if="activeTab!=='setup'" class="secondary" @click="backToSetup">← 返回 Set Up</button></header>
<nav v-if="activeTab==='setup'" class="top-nav"><button class="active">Set Up</button></nav>
<div v-else-if="selectedTask" class="task-subnav"><div class="crumb"><button @click="backToSetup">Set Up</button><span>›</span><strong>{{ selectedTask.name }}</strong></div><nav><button v-for="tab in resultTabs" :key="tab[0]" :class="{active:activeTab===tab[0]}" @click="activeTab=tab[0]">{{ tab[1] }}</button></nav></div>

<section v-if="activeTab==='setup'" class="workspace setup-layout">
<div class="panel full common-input"><div class="panel-head"><div><span>COMMON INPUT</span><h2>公共输入</h2></div></div><div class="form-grid two"><label><span>当前项目</span><input v-model="common.project" placeholder="项目名称"></label><label><span>GDS 文件</span><input v-model="common.gdsName" placeholder="example.gds"></label></div></div>

<div class="panel"><div class="panel-head"><div><span>DENSITY TASK</span><h2>创建 density 分析任务</h2></div><button class="primary" @click="createDensityTask('form')">创建 density 任务</button></div><div class="form-grid"><label><span>GDS layer</span><input v-model="densityForm.layer"></label><label><span>对比 layer</span><input v-model="densityForm.compareLayer"></label><label><span>窗口 step</span><input v-model.number="densityForm.stepUm" type="number"></label><label><span>窗口宽度</span><input v-model.number="densityForm.widthUm" type="number"></label><label><span>窗口高度</span><input v-model.number="densityForm.heightUm" type="number"></label><label><span>负 Gradient Spec</span><input v-model.number="densityForm.negativeSpec" type="number" step="0.005"></label><label><span>正 Gradient Spec</span><input v-model.number="densityForm.positiveSpec" type="number" step="0.005"></label></div></div>

<div class="panel"><div class="panel-head"><div><span>PATTERN MATCH TASK</span><h2>创建 pattern match 任务</h2></div><button class="primary" @click="createPatternTask">创建 pattern match 任务</button></div><div class="form-grid one"><label><span>pattern 文件</span><input v-model="patternForm.patternFile" placeholder="pattern.xml / pattern.gds"></label></div><div class="pattern-hint">使用公共输入中的当前项目与 GDS 文件，对指定 pattern 文件执行匹配。</div></div>

<div class="panel full"><div class="panel-head"><div><span>TCL COMMAND</span><h2>在 Set Up 中调用 TCL command</h2></div></div><div class="terminal"><div class="terminal-log"><div v-if="!tclLog.length" class="terminal-empty">示例：density::analyze -layer M1 -step 100</div><div v-for="(l,i) in tclLog" :key="i"><p><small>{{ l.time }}</small> $ {{ l.command }}</p><pre>{{ l.output }}</pre></div></div><form @submit.prevent="runTcl"><span>$</span><input v-model="tclInput"><button>运行</button></form></div></div>

<div class="panel full"><div class="panel-head"><div><span>TASKS</span><h2>已创建任务</h2></div><small>density 和 pattern match 任务均可勾选；结果只能从这里进入</small></div><div v-if="!tasks.length" class="empty">暂无任务</div><table v-else><thead><tr><th><input type="checkbox" :checked="allSelected" @change="toggleAll"></th><th>任务</th><th>类型</th><th>项目</th><th>GDS</th><th>任务输入</th><th>来源</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id" :class="{selected:selectedTaskIds.includes(task.id)}"><td><input type="checkbox" :checked="selectedTaskIds.includes(task.id)" @change="toggleTask(task.id)"></td><td><strong>{{ task.name }}</strong></td><td>{{ task.type==='density'?'density':'pattern match' }}</td><td>{{ task.project }}</td><td>{{ task.gdsName }}</td><td>{{ task.type==='density'?`${task.layer} · ${task.stepUm} µm`:task.patternFile }}</td><td>{{ task.source==='tcl'?'TCL':'表单' }}</td><td><span :class="task.type==='density'?(task.result.pass?'ok-pill':'warn-pill'):(task.result.matched?'ok-pill':'warn-pill')">{{ task.type==='density'?(task.result.pass?'通过':'需检查'):(task.result.matched?'Match':'No Match') }}</span></td><td><button class="link" @click="openTask(task)">查看结果</button></td></tr></tbody></table></div>
</section>

<section v-else-if="selectedTask" class="workspace result-grid">
<div class="panel full task-summary"><div><span>任务</span><strong>{{ selectedTask.name }}</strong></div><div><span>类型</span><strong>{{ selectedTask.type==='density'?'density':'pattern match' }}</strong></div><div><span>项目</span><strong>{{ selectedTask.project }}</strong></div><div><span>GDS</span><strong>{{ selectedTask.gdsName }}</strong></div><div><span>输入</span><strong>{{ selectedTask.type==='density'?selectedTask.layer:selectedTask.patternFile }}</strong></div></div>

<template v-if="selectedTask.type==='pattern'&&activeTab==='pattern'">
<div class="metric"><span>是否 match</span><strong :class="selectedTask.result.matched?'ok-text':'warn-text'">{{ selectedTask.result.matched?'Match':'No Match' }}</strong></div><div class="metric"><span>match 数量</span><strong>{{ selectedTask.result.count }}</strong></div><div class="metric"><span>匹配分数</span><strong>{{ selectedTask.result.score.toFixed(3) }}</strong></div><div class="panel full pattern-result"><div class="panel-head"><div><span>PATTERN MATCH</span><h2>{{ selectedTask.patternFile }} 匹配结果</h2></div></div><div class="match-summary"><div><span>GDS</span><strong>{{ selectedTask.gdsName }}</strong></div><div><span>pattern 文件</span><strong>{{ selectedTask.patternFile }}</strong></div><div><span>判定</span><strong :class="selectedTask.result.matched?'ok-text':'warn-text'">{{ selectedTask.result.matched?'已匹配到 pattern':'未匹配到 pattern' }}</strong></div><div><span>匹配数量</span><strong>{{ selectedTask.result.count }}</strong></div></div></div>
</template>

<template v-if="selectedTask.type==='density'&&activeTab==='results'">
<div class="metric"><span>平均 density</span><strong>{{ selectedTask.result.mean.toFixed(4) }}</strong></div><div class="metric"><span>方差</span><strong>{{ selectedTask.result.variance.toFixed(5) }}</strong></div><div class="metric"><span>均匀性 p-value</span><strong>{{ selectedTask.result.pValue.toFixed(3) }}</strong></div><div class="metric"><span>最大 |density gradient|</span><strong>{{ selectedTask.result.maxAbsGradient.toFixed(4) }}</strong></div><div class="metric"><span>综合结果</span><strong :class="selectedTask.result.pass?'ok-text':'warn-text'">{{ selectedTask.result.pass?'通过':'需检查' }}</strong></div><div class="panel full"><div class="panel-head"><div><span>HEATMAP</span><h2>{{ selectedTask.layer }} density heatmap</h2></div></div><div class="heatmap"><i v-for="(v,i) in selectedTask.result.values" :key="i" :style="{background:heatColor(v)}" :title="`row ${Math.floor(i/15)+1}, col ${(i%15)+1}, value ${v.toFixed(4)}`"></i></div><div class="colorbar"><span>0.3800</span><div></div><span>0.5900</span></div><div class="hover-note">鼠标悬浮到 heatmap 单元格可查看具体小数 value。</div></div>
</template>

<template v-else-if="selectedTask.type==='density'&&activeTab==='compare'">
<div class="panel full"><div class="panel-head"><div><span>LAYER COMPARE</span><h2>不同 layer 同区域 heatmap 对比</h2></div></div><div class="dual-heat"><div><h3>{{ selectedTask.layer }}</h3><div class="heatmap"><i v-for="(v,i) in selectedTask.result.values" :key="i" :style="{background:heatColor(v)}" :title="`${selectedTask.layer} · row ${Math.floor(i/15)+1}, col ${(i%15)+1}, value ${v.toFixed(4)}`"></i></div><div class="colorbar"><span>0.3800</span><div></div><span>0.5900</span></div></div><div><h3>{{ selectedTask.compareLayer }}</h3><div class="heatmap"><i v-for="(v,i) in compareValues" :key="i" :style="{background:heatColor(v)}" :title="`${selectedTask.compareLayer} · row ${Math.floor(i/15)+1}, col ${(i%15)+1}, value ${v.toFixed(4)}`"></i></div><div class="colorbar"><span>0.3800</span><div></div><span>0.5900</span></div></div></div><div class="compare-cards"><div><span>{{ selectedTask.layer }} mean</span><strong>{{ selectedTask.result.mean.toFixed(4) }}</strong></div><div><span>{{ selectedTask.compareLayer }} mean</span><strong>{{ (compareValues.reduce((a,b)=>a+b,0)/compareValues.length).toFixed(4) }}</strong></div><div><span>区域相关性</span><strong>0.936</strong></div></div></div>
</template>

<template v-else-if="selectedTask.type==='density'&&activeTab==='gradient'">
<div class="panel full"><div class="panel-head"><div><span>GRADIENT SPEC</span><h2>Signed density gradient 分布与双边 Spec</h2></div><div class="dual-spec"><label><span>负 Spec</span><input v-model.number="selectedTask.negativeSpec" type="number" step="0.005" @input="updateSpecs"></label><label><span>正 Spec</span><input v-model.number="selectedTask.positiveSpec" type="number" step="0.005" @input="updateSpecs"></label></div></div><div class="hist-chart"><div v-for="(b,i) in gradientBins" :key="i" class="hist-col"><div class="bar" :style="{height:`${Math.max(4,b.count/Math.max(...gradientBins.map(x=>x.count))*180)}px`}"><small>{{ b.count }}</small></div><span>{{ b.lo.toFixed(3) }}</span></div><div class="zero-line" :style="{left:'50%'}"><b>0</b></div><div class="spec-line neg" :style="{left:`${specPosition(selectedTask.negativeSpec)}%`}"><b>{{ selectedTask.negativeSpec.toFixed(3) }}</b></div><div class="spec-line pos" :style="{left:`${specPosition(selectedTask.positiveSpec)}%`}"><b>+{{ selectedTask.positiveSpec.toFixed(3) }}</b></div></div><div class="spec-cards"><div><span>最小 gradient</span><strong>{{ Math.min(...selectedTask.result.signedGradients).toFixed(4) }}</strong></div><div><span>最大 gradient</span><strong>{{ Math.max(...selectedTask.result.signedGradients).toFixed(4) }}</strong></div><div><span>判定</span><strong :class="selectedTask.result.pass?'ok-text':'warn-text'">{{ selectedTask.result.pass?'全部落在双边 Spec 内':'存在超 Spec gradient' }}</strong></div></div></div>
</template>

<template v-else-if="selectedTask.type==='density'&&activeTab==='history'">
<div class="panel full"><div class="panel-head"><div><span>HISTORY</span><h2>历史项目 density 与 density gradient 对比</h2></div></div><div class="history-legend"><span><i class="density-dot"></i>density</span><span><i class="gradient-dot"></i>density gradient</span></div><div class="dual-bar-chart"><div v-for="row in historyData" :key="row.project" class="project-group"><div class="bar-pair"><div class="density-bar" :style="{height:`${row.density*300}px`}" :title="`density ${row.density.toFixed(4)}`"><b>{{ row.density.toFixed(3) }}</b></div><div class="gradient-bar" :style="{height:`${row.gradient*1600}px`}" :title="`density gradient ${row.gradient.toFixed(4)}`"><b>{{ row.gradient.toFixed(3) }}</b></div></div><span>{{ row.project }}</span></div></div><table><thead><tr><th>项目</th><th>layer</th><th>density</th><th>density gradient</th><th>备注</th></tr></thead><tbody><tr v-for="(row,i) in historyData" :key="row.project"><td>{{ row.project }}</td><td>{{ selectedTask.layer }}</td><td>{{ row.density.toFixed(4) }}</td><td>{{ row.gradient.toFixed(4) }}</td><td>{{ i===0?'当前任务':'历史项目' }}</td></tr></tbody></table></div>
</template>

<template v-else-if="activeTab==='fa'">
<div class="panel full"><div class="panel-head"><div><span>FA LIBRARY</span><h2>关联 FA Library case</h2></div><small>状态列替换为构造的 SEM 图</small></div><table><thead><tr><th>Case ID</th><th>项目</th><th>产品</th><th>工艺</th><th>fail type</th><th>fail model</th><th>layer</th><th>SEM 图</th></tr></thead><tbody><tr v-for="row in faCases" :key="row.caseId"><td><strong>{{ row.caseId }}</strong></td><td>{{ row.project }}</td><td>{{ row.product }}</td><td>{{ row.technology }}</td><td>{{ row.failType }}</td><td>{{ row.failModel }}</td><td>{{ row.layer }}</td><td><div class="sem-thumb" :class="`sem-${row.sem}`"><span>SEM</span><i></i></div></td></tr></tbody></table></div>
</template>
</section>
</main>
</template>

<style scoped>
