p:14px;padding:10px 12px;background:#f8fafc;border-radius:7px;color:#667085;font-size:11px}.terminal{height:245px;background:#101720;color:#d7e0ea;border-radius:8px;display:flex;flex-direction:column;overflow:hidden}.terminal-log{flex:1;overflow:auto;padding:12px}.terminal-log p{margin:0 0 4px;font-size:12px}.terminal-log pre{margin:0 0 12px;color:#9fd8b7}.terminal-empty{color:#8190a3}.terminal form{display:flex;gap:8px;border-top:1px solid #263446;padding:8px}.terminal input{flex:1;background:transparent;border:0;outline:0;color:#fff}.terminal button{background:#1e293b;color:#fff;border:1px solid #475569;border-radius:5px;padding:0 12px}.panel table{width:100%;border-collapse:collapse;font-size:12px}.panel th,.panel td{padding:11px 10px;border-bottom:1px solid #edf0f4;text-align:left;vertical-align:middle}.panel tbody tr.selected{background:#f5f8ff}.link{border:0;background:none;color:#2563eb;font-weight:700}.ok-pill,.warn-pill{display:inline-flex;padding:3px 8px;border-radius:999px}.ok-pill{background:#e7f7ef;color:#087553}.warn-pill{background:#fff1e8;color:#b54708}.empty{padding:30px;text-align:center;color:#7b8490}.task-summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.task-summary span,.metric span,.compare-cards span,.spec-cards span,.match-summary span{display:block;font-size:10px;color:#7b8490;margin-bottom:5px}.task-summary strong{font-size:12px}.metric strong{font-size:20px}.ok-text{color:#087553}.warn-text{color:#b54708}.match-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.match-summary>div{padding:14px;background:#f8fafc;border-radius:8px}.heatmap{display:grid;grid-template-columns:repeat(15,1fr);gap:3px}.heatmap i{aspect-ratio:1;border-radius:2px;cursor:crosshair}.colorbar{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:10px;color:#667085}.colorbar div{height:9px;flex:1;border-radius:99px;background:linear-gradient(90deg,hsl(220 76% 52%),hsl(125 76% 52%),hsl(30 76% 52%))}.dual-heat{displa